import * as Phaser from 'phaser';
import { ACCENT, VILLAIN } from './palette';
import { bolt, forge, path, poly, rand, seeded } from './draw';
import { buildAllRealms } from './realm';

/**
 * Arena texture entry point.
 *
 * Per-realm sky, parallax silhouettes and platform material are generated by
 * the shared config-driven renderer in `realm.ts` — one implementation for all
 * six realms, each contributing only a `RealmEnvironment`. What remains here
 * are the realm-agnostic props shared across scenes.
 */
export function buildArena(scene: Phaser.Scene) {
  buildAllRealms(scene);

  // Soft cloud band used in the intro cinematic and the sky realms.
  forge(scene, 'cloud_band', 1024, 260, (g) => {
    const r = seeded(211);
    for (let i = 0; i < 40; i++) {
      const x = r() * 1024;
      const y = 40 + r() * 180;
      const w = 160 + r() * 340;
      const h = 30 + r() * 70;
      g.fillStyle(0x1b2236, 0.08 + r() * 0.1);
      g.fillEllipse(x, y, w, h);
    }
  });

  // Reusable lightning streak for storm flashes.
  forge(scene, 'lightning_streak', 180, 420, (g) => {
    const r = seeded(307);
    bolt(g, { x: 90, y: 0 }, { x: 90 + rand(r, -40, 40), y: 420 }, VILLAIN.energy, 4, 34, 12, r, 0.9);
    bolt(g, { x: 90, y: 60 }, { x: 150, y: 260 }, VILLAIN.energy, 2.4, 20, 7, r, 0.6);
  });

  /* ---- Static hazard props -------------------------------------------
     Shapes are deliberately distinct from platform silhouettes: spikes are
     upward triangles, emitters are hexagonal housings, corruption is a
     ragged organic blob. Colour alone never signals danger. */

  // Spike bed — tiles horizontally along a ground run.
  forge(scene, 'hazard_spikes', 64, 48, (g) => {
    for (let i = 0; i < 4; i++) {
      const x = i * 16;
      poly(g, [{ x, y: 48 }, { x: x + 8, y: 4 }, { x: x + 16, y: 48 }], 0x2b3a4d, 1);
      poly(g, [{ x: x + 5, y: 48 }, { x: x + 8, y: 8 }, { x: x + 11, y: 48 }], 0xd9e8f2, 0.9);
    }
    g.fillStyle(0x111820, 1);
    g.fillRect(0, 44, 64, 4);
  });

  // Laser emitter housing — top and bottom of a gate.
  forge(scene, 'hazard_emitter', 36, 28, (g) => {
    poly(
      g,
      [{ x: 4, y: 0 }, { x: 32, y: 0 }, { x: 36, y: 14 }, { x: 32, y: 28 }, { x: 4, y: 28 }, { x: 0, y: 14 }],
      0x1d2430,
      1
    );
    g.lineStyle(1.5, 0x8395a5, 0.9);
    g.strokeRect(5, 5, 26, 18);
    g.fillStyle(0xff243d, 1);
    g.fillCircle(18, 14, 4);
  });

  // Corruption patch — organic, clearly not a surface you can stand on.
  forge(scene, 'hazard_corruption', 128, 40, (g) => {
    const r = seeded(733);
    g.fillStyle(0x18070c, 0.95);
    g.fillEllipse(64, 28, 126, 28);
    for (let i = 0; i < 18; i++) {
      g.fillStyle(r() > 0.5 ? 0xff243d : 0xc9102b, 0.25 + r() * 0.5);
      g.fillEllipse(r() * 128, 18 + r() * 20, 10 + r() * 30, 6 + r() * 14);
    }
    for (let i = 0; i < 7; i++) {
      const x = r() * 128;
      path(g, [{ x, y: 34 }, { x: x + rand(r, -6, 6), y: 6 + r() * 12 }], 0xff6678, 0.5, 1.4);
    }
  });

  // Animated molten surface drawn under the ground lip in the fire realms.
  forge(scene, 'lava_surface', 512, 64, (g) => {
    const r = seeded(419);
    g.fillStyle(ACCENT.magma, 1);
    g.fillRect(0, 0, 512, 64);
    for (let i = 0; i < 40; i++) {
      g.fillStyle(r() > 0.5 ? ACCENT.emberHot : ACCENT.ember, 0.2 + r() * 0.5);
      g.fillEllipse(r() * 512, r() * 64, 20 + r() * 90, 6 + r() * 16);
    }
    g.fillStyle(ACCENT.emberHot, 0.5);
    g.fillRect(0, 0, 512, 4);
  });
}
